// EFX Router — normalise inputs, apply defaults, build the scripts.run request body.
// Contract (N8n.js): every alias is n8n_<name>(actor, ...args) → this node always puts actor at parameters[0].
const sd = $getWorkflowStaticData('global');
const inp = $input.first().json;

const fn = String(inp.fn || '').trim();
if (!/^n8n_[A-Za-z0-9_]+$/.test(fn)) throw new Error('EFX E_VALIDATION: fn must be an n8n_* alias from N8n.js (got "' + fn + '")');

let args = inp.args;
if (typeof args === 'string' && args.trim()) { try { args = JSON.parse(args); } catch (e) { throw new Error('EFX E_VALIDATION: args is a string but not valid JSON'); } }
if (args === undefined || args === null || args === '') args = [];
if (!Array.isArray(args)) args = [args];

let actor = inp.actor;
if (typeof actor === 'string' && actor.trim()) { try { actor = JSON.parse(actor); } catch (e) { actor = { id: actor }; } }
if (!actor || typeof actor !== 'object' || Array.isArray(actor)) actor = {};
// Default actor: the calling workflow should pass its own; otherwise attribute to this router.
const defaults = { id: 'n8n:' + $workflow.name, email: 'efx-bot@team-group.com', display: $workflow.name + ' (n8n)' };
actor = Object.assign({}, defaults, Object.fromEntries(Object.entries(actor).filter(([k, v]) => v !== undefined && v !== null && v !== '')));
if (!inp.actor || !inp.actor.display) actor.display = (actor.id !== defaults.id) ? String(actor.id).replace(/^n8n:/, '') + ' (n8n)' : defaults.display;

const raw = inp.treatAlreadyClosedAsSuccess;
const treatAlreadyClosedAsSuccess = (raw === undefined || raw === null || raw === '') ? true : (raw === true || String(raw).toLowerCase() === 'true');

// Idempotency (best effort): replay a cached envelope for the same key within 10 minutes.
// NOTE: $getWorkflowStaticData persists only for production (non-manual) executions.
const idempotencyKey = String(inp.idempotencyKey || '').trim();
const TTL_MS = 10 * 60 * 1000; const now = Date.now();
sd.idem = sd.idem || {};
for (const k of Object.keys(sd.idem)) if (now - (sd.idem[k].at || 0) > TTL_MS) delete sd.idem[k];
const hit = idempotencyKey && sd.idem[idempotencyKey] ? sd.idem[idempotencyKey].out : null;

return [{ json: {
  fn, args, actor, idempotencyKey, treatAlreadyClosedAsSuccess,
  cacheHit: !!hit, cached: hit || null, startedAt: now,
  request: { function: fn, parameters: [actor].concat(args), devMode: false }
} }];

// EFX Router — unwrap the Execution API response and apply the guard rule.
// Execution API shapes:
//   HTTP 4xx/5xx           → { error: { code, message, status } }                       → E_TRANSPORT
//   script threw           → { done: true, error: { code: 3, message, details: [...] } } → E_SCRIPT
//   ok                     → { done: true, response: { '@type': ..., result: <alias return> } }
// The alias return is the EFX envelope { ok, apiVersion, requestId, result } | { ok:false, error:{code,message,fields?} }.
const inp = $('Set defaults').first().json;
const r = $input.first().json;
const status = Number(r.statusCode || 0);
let body = (r.body !== undefined ? r.body : r.data);   // n8n HTTP v4.2: responseFormat "text" + fullResponse puts the payload in .data, not .body
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
const _raw = (r.body !== undefined ? r.body : r.data);
const snippet = typeof _raw === 'string' ? _raw.slice(0, 300) : JSON.stringify(_raw || '').slice(0, 300);

function fail(code, message, requestId) {
  // Message format is stable on purpose: error workflows can regex /^EFX (E_[A-Z_]+):/ to branch on the code.
  // n8n's Code node parses "Name: rest" and DROPS the leading "EFX <code>: " from error.message
    // (it survives only in error.stack), and splits mid-JSON when the message contains colons.
    // So the code is ALSO appended as a trailing tag, which n8n never strips. Branch on that.
    throw new Error('EFX ' + code + ': ' + message + ' [fn=' + inp.fn + (requestId ? ', requestId=' + requestId : '') + '] [efxCode=' + code + ']');
}

if (!body || typeof body !== 'object') fail('E_TRANSPORT', 'Non-JSON response from script.googleapis.com (HTTP ' + status + '): ' + snippet);
if (status >= 400 || (body.error && body.done !== true)) {
  const ge = body.error || {};
  fail('E_TRANSPORT', 'Execution API HTTP ' + status + ' ' + (ge.status || '') + ': ' + (ge.message || snippet)
    + ' — check: SA credential + impersonation of efx-bot@team-group.com, script linked to the SA\'s GCP project, API-executable deployment, script.projects scope, <<EFX_SCRIPT_ID>> replaced');
}
if (body.done !== true) fail('E_TRANSPORT', 'Execution API returned done=false');
if (body.error) {
  const d = (body.error.details && body.error.details[0]) || {};
  const trace = Array.isArray(d.scriptStackTraceElements) ? ' @ ' + d.scriptStackTraceElements.map(s => s.function + ':' + s.lineNumber).join(' < ') : '';
  fail('E_SCRIPT', (d.errorType ? d.errorType + ': ' : '') + (d.errorMessage || body.error.message || 'Apps Script error') + trace);
}

const env = body.response ? body.response.result : undefined;
if (env === undefined || env === null) fail('E_SCRIPT', 'Function returned nothing — not an n8n_* alias, or it returned undefined');
if (typeof env !== 'object' || typeof env.ok !== 'boolean') fail('E_SCRIPT', 'Return value is not an EFX envelope {ok,...}: ' + JSON.stringify(env).slice(0, 300));

const meta = { fn: inp.fn, requestId: env.requestId || null, apiVersion: env.apiVersion || null, tookMs: Date.now() - inp.startedAt };
let out;
if (env.ok === false) {
  const err = env.error || {}; const code = err.code || 'E_UNKNOWN';
  if (code === 'E_ALREADY_CLOSED' && inp.treatAlreadyClosedAsSuccess) {
    out = Object.assign({ ok: true, alreadyClosed: true, code, message: err.message || '' }, meta);   // safe no-op for closers
  } else {
    fail(code, (err.message || 'no message') + (err.fields ? ' fields=' + JSON.stringify(err.fields) : ''), env.requestId);
  }
} else {
  const res = env.result;
  out = Object.assign({ ok: true }, (res && typeof res === 'object' && !Array.isArray(res)) ? res : { value: res }, meta);
  for (const k of Object.keys(env)) if (!['ok', 'apiVersion', 'requestId', 'result'].includes(k)) out[k] = env[k];   // e.g. record, employeeId
}

if (inp.idempotencyKey) { const sd = $getWorkflowStaticData('global'); sd.idem = sd.idem || {}; sd.idem[inp.idempotencyKey] = { at: Date.now(), out }; }
return [{ json: out }];
